const body = $json.body || $json;

const itemId =
  body.itemId ||
  body.pulseId ||
  body.event?.itemId ||
  body.event?.pulseId ||
  body.inputFields?.itemId ||
  body.inputFields?.pulseId ||
  body.item?.id ||
  "";

const boardId =
  body.boardId ||
  body.event?.boardId ||
  body.inputFields?.boardId ||
  "";

return [
  {
    json: {
      itemId: String(itemId),
      boardId: String(boardId)
    }
  }
];

const item = $json;

// Normaliza texto
function normalizeText(str) {
  return String(str || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .trim();
}

// Busca columna por type, title o id
function findColumn(cols, { types = [], titleIncludes = [], idIncludes = [] }) {
  return (cols || []).find((c) => {
    const type = normalizeText(c.type);
    const title = normalizeText(c.column?.title);
    const id = normalizeText(c.id);

    const typeMatch = types.some((t) => type === normalizeText(t));
    const titleMatch = titleIncludes.some((t) => title.includes(normalizeText(t)));
    const idMatch = idIncludes.some((t) => id.includes(normalizeText(t)));

    return typeMatch || titleMatch || idMatch;
  });
}

function parseColumnValue(col) {
  if (!col || !col.value) return null;

  try {
    return JSON.parse(col.value);
  } catch {
    return col.value;
  }
}

const cols = item.column_values || [];

// EMAIL
const emailCol = findColumn(cols, {
  types: ["email"],
  titleIncludes: ["email", "e-mail", "correo", "mail"],
  idIncludes: ["email", "mail"]
});

const emailParsed = parseColumnValue(emailCol);

let email = "";
if (emailParsed && typeof emailParsed === "object" && emailParsed.email) {
  email = emailParsed.email;
} else if (emailCol?.text) {
  email = emailCol.text;
}

email = String(email || "").trim().toLowerCase();

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!emailRegex.test(email)) {
  email = "";
}

