const phoneCol = findColumn(cols, {
  types: ["phone"],
  titleIncludes: ["telefono", "teléfono", "tel", "phone", "whatsapp", "celular", "movil", "móvil"],
  idIncludes: ["phone", "telefono", "tel", "whatsapp", "cel"]
});

const phoneParsed = parseColumnValue(phoneCol);

let phone = "";
if (phoneParsed && typeof phoneParsed === "object" && phoneParsed.phone) {
